#include <print>

int main() {
    int coins[] = {100, 50, 20, 10, 5, 1};
    int small_first[] = {1, 5, 10, 20, 50, 100};

    int amount = 443;
    int total = 0;
    for (int c : coins) {
        int n = amount / c;
        if (n > 0) std::println("{}元 × {}张", c, n);
        total += n;
        amount %= c;
    }
    std::println("合计 {} 张，剩余零头 {}", total, amount);

    int left = 443, wrong = 0;
    for (int c : small_first) {
        wrong += left / c;
        left %= c;
    }
    std::println("从小拿的话给出 {} 张", wrong);
    return 0;
}

